class Base:
    def run(self, providers):
        return providers['base']()
class Child(Base):
    def run(self, providers):
        return providers['child']()

class Base:
    def run(self, value):
        return value
class Child(Base):
    def run(self, value):
        return value

class Base:
    def __init__(self):
        self.token = None
class Child(Base):
    def __init__(self, token):
        self.token = token

class Base:
    def run(self, events):
        events.append('parent')
class Child(Base):
    def run(self, events):
        events.append('before')
        super().run(events)
        events.append('after')

class Base:
    def run(self, emit):
        emit('parent')
class Child(Base):
    def run(self, emit):
        emit('before')
        super().run(emit)
        emit('after')

class Base:
    def run(self, labels):
        labels.add('parent')
class Child(Base):
    def run(self, labels):
        labels.add('child')
        super().run(labels)

class Base:
    def run(self, events):
        self.ready = True
class Child(Base):
    def run(self, events):
        super().run(events)
        events.append(self.ready)

class Base:
    def run(self, events):
        events.append('parent')
class Child(Base):
    def run(self, events):
        super().run(events)

class Base:
    def run(self, events):
        pass
class Child(Base):
    def run(self, events):
        super().run(events)
